            _ = &sig_size;
            const prev_data_slice = self.data.items[(if (comptime @typeInfo(@TypeOf(original_fileoff)) == .@"enum") cp_cast_int(usize, @intFromEnum(original_fileoff)) else cp_cast_int(usize, original_fileoff))..];
