.SYMTAB => {
const sz: usize = @sizeOf(macho.symtab_command);
                var symtab = (blk: {
                break :blk (std.mem.bytesAsValue(macho.symtab_command, self.data.items[cmd_off..][0..sz])).*;

});
                _ = &symtab;
                symtab.symoff = try shifter.do(symtab.symoff);
                symtab.stroff = try shifter.do(symtab.stroff);
                const symtab_const = symtab;
                _ = @memcpy(self.data.items[cmd_off..][0..sz], std.mem.asBytes((&symtab_const)));
},
.DYSYMTAB => {
const sz: usize = @sizeOf(macho.dysymtab_command);
                var dysymtab = (blk: {
                break :blk (std.mem.bytesAsValue(macho.dysymtab_command, self.data.items[cmd_off..][0..sz])).*;

});
                _ = &dysymtab;
                dysymtab.tocoff = try shifter.do(dysymtab.tocoff);
                dysymtab.modtaboff = try shifter.do(dysymtab.modtaboff);
                dysymtab.extrefsymoff = try shifter.do(dysymtab.extrefsymoff);
                dysymtab.indirectsymoff = try shifter.do(dysymtab.indirectsymoff);
                dysymtab.extreloff = try shifter.do(dysymtab.extreloff);
                dysymtab.locreloff = try shifter.do(dysymtab.locreloff);
                const dysymtab_const = dysymtab;
                _ = @memcpy(self.data.items[cmd_off..][0..sz], std.mem.asBytes((&dysymtab_const)));
},
.DYLD_CHAINED_FIXUPS, .CODE_SIGNATURE, .FUNCTION_STARTS, .DATA_IN_CODE, .DYLIB_CODE_SIGN_DRS, .LINKER_OPTIMIZATION_HINT, .DYLD_EXPORTS_TRIE => {
const sz: usize = @sizeOf(macho.linkedit_data_command);
                var linkedit_cmd = (blk: {
                break :blk (std.mem.bytesAsValue(macho.linkedit_data_command, self.data.items[cmd_off..][0..sz])).*;

});
                _ = &linkedit_cmd;
                linkedit_cmd.dataoff = try shifter.do(linkedit_cmd.dataoff);
                if ((cmd.cmd == .CODE_SIGNATURE)) {
                    linkedit_cmd.datasize = (if (comptime @typeInfo(@TypeOf(sig_size)) == .@"enum") cp_cast_int(u32, @intFromEnum(sig_size)) else cp_cast_int(u32, sig_size));
                }
                const linkedit_const = linkedit_cmd;
                _ = @memcpy(self.data.items[cmd_off..][0..sz], std.mem.asBytes((&linkedit_const)));
},
.DYLD_INFO, .DYLD_INFO_ONLY => {
const sz: usize = @sizeOf(macho.dyld_info_command);
                var dyld_info = (blk: {
                break :blk (std.mem.bytesAsValue(macho.dyld_info_command, self.data.items[cmd_off..][0..sz])).*;

});
                _ = &dyld_info;
                dyld_info.rebase_off = try shifter.do(dyld_info.rebase_off);
                dyld_info.bind_off = try shifter.do(dyld_info.bind_off);
                dyld_info.weak_bind_off = try shifter.do(dyld_info.weak_bind_off);
                dyld_info.lazy_bind_off = try shifter.do(dyld_info.lazy_bind_off);
                dyld_info.export_off = try shifter.do(dyld_info.export_off);
                const dyld_const = dyld_info;
                _ = @memcpy(self.data.items[cmd_off..][0..sz], std.mem.asBytes((&dyld_const)));
},
else => {

},
}
            }
    }

pub fn iterator(self: MachoFile) macho.LoadCommandIterator {
            return macho.LoadCommandIterator{ .buffer = self.data.items[@sizeOf(macho.mach_header_64)..][0..self.header.sizeofcmds], .ncmds = self.header.ncmds };
    }

pub fn build(self: *MachoFile, writer: anytype) !void {
            _ = try writer.writeAll(self.data.items);
    }

pub fn validateSegments(self: *MachoFile) !void {
            var iter = self.iterator();
            _ = &iter;
            var prev_end: u64 = 0;
            _ = &prev_end;
            while (iter.next()) |entry| {
                const cmd = entry.hdr;
                if ((cmd.cmd == .SEGMENT_64)) {
                    const seg = (entry.cast(macho.segment_command_64)).?;
                    if ((seg.fileoff < prev_end)) {
                        return error.OverlappingSegments;
                    }
                    prev_end = (seg.fileoff + seg.filesize);
                }
            }
    }

pub fn buildAndSign(self: *MachoFile, writer: *std.Io.Writer) !void {
            if (((self.header.cputype == macho.CPU_TYPE_ARM64) and (!bun.feature_flag.BUN_NO_CODESIGN_MACHO_BINARY.get()))) {
                var out_data = std.array_list.Managed(u8).init(self.allocator);
                _ = &out_data;
                defer {
                _ = out_data.deinit();
                }
                _ = try self.build(out_data.writer());
                var signer = try MachoSigner.init(self.allocator, out_data.items);
                _ = &signer;
                defer {
                _ = signer.deinit();
                }
                _ = try signer.sign(writer);
            } else {
                _ = try self.build(writer);
            }
    }
};

pub const utils = struct {

pub fn isElf(data: []const u8) bool {
            if ((data.len < 4)) {
                return false;
            }
            return (mem.readInt(u32, data[0..4], .big) == 2135247942);
    }

pub fn isMacho(data: []const u8) bool {
            if ((data.len < 4)) {
                return false;
            }
            return (mem.readInt(u32, data[0..4], .little) == macho.MH_MAGIC_64);
    }
};


pub fn alignSize(size: u64, base: u64) u64 {
        const over = (size % base);
        return (if ((over == 0)) size else (size + (base - over)));
}

pub fn alignVmsize(size: u64, page_size: u64) u64 {
        const min_sz: u64 = 16384;
        const effective = (if ((size > min_sz)) size else min_sz);
        return alignSize(effective, page_size);
}
